package com.example.examplemod.community;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.level.saveddata.SavedData;
import java.util.*;
/** Project discussions/planning proposals and voluntary recruiting preferences, independent of money and roles. */
public final class ProjectWorkspaceData extends SavedData {
    public record Message(UUID id,UUID author,String name,String text,long time){}
    public record Mark(UUID id,UUID author,String text,int x1,int z1,int x2,int z2,boolean approved){}
    public static final class Room {public long revision;public final List<Message> chat=new ArrayList<>();public final LinkedHashMap<UUID,Mark> marks=new LinkedHashMap<>();public final LinkedHashSet<UUID> receipts=new LinkedHashSet<>();}
    public final Map<UUID,Room> rooms=new HashMap<>();public final Map<UUID,Integer> recruiting=new HashMap<>();
    public Room room(UUID id){return rooms.computeIfAbsent(id,k->new Room());}
    public static ProjectWorkspaceData get(MinecraftServer s){return s.overworld().getDataStorage().computeIfAbsent(new Factory<>(ProjectWorkspaceData::new,ProjectWorkspaceData::load,null),"ccec_project_workspaces");}
    public boolean receipt(Room room,UUID nonce){if(room.receipts.contains(nonce))return false;room.receipts.add(nonce);while(room.receipts.size()>256)room.receipts.remove(room.receipts.iterator().next());room.revision++;setDirty();return true;}
    @Override public CompoundTag save(CompoundTag root,HolderLookup.Provider lookup){root.putInt("Version",1);var list=new ListTag();rooms.forEach((id,room)->{var t=new CompoundTag();t.putUUID("Project",id);t.putLong("Revision",room.revision);var messages=new ListTag();for(var m:room.chat){var n=new CompoundTag();n.putUUID("Id",m.id);n.putUUID("Author",m.author);n.putString("Name",m.name);n.putString("Text",m.text);n.putLong("Time",m.time);messages.add(n);}t.put("Chat",messages);var marks=new ListTag();for(var m:room.marks.values()){var n=new CompoundTag();n.putUUID("Id",m.id);n.putUUID("Author",m.author);n.putString("Text",m.text);n.putInt("X1",m.x1);n.putInt("Z1",m.z1);n.putInt("X2",m.x2);n.putInt("Z2",m.z2);n.putBoolean("Approved",m.approved);marks.add(n);}t.put("Marks",marks);var receipts=new ListTag();room.receipts.forEach(r->receipts.add(NbtUtils.createUUID(r)));t.put("Receipts",receipts);list.add(t);});root.put("Rooms",list);var workers=new ListTag();recruiting.forEach((id,mask)->{var t=new CompoundTag();t.putUUID("Id",id);t.putInt("Interests",mask);workers.add(t);});root.put("Recruiting",workers);return root;}
    public static ProjectWorkspaceData load(CompoundTag root,HolderLookup.Provider lookup){if(root.getInt("Version")>1)throw new IllegalArgumentException("Workspace version");var d=new ProjectWorkspaceData();for(Tag raw:root.getList("Rooms",10)){var t=(CompoundTag)raw;var room=d.room(t.getUUID("Project"));room.revision=t.getLong("Revision");for(Tag value:t.getList("Chat",10)){var m=(CompoundTag)value;if(room.chat.size()<100&&m.getString("Text").length()<=256&&m.getString("Name").length()<=128)room.chat.add(new Message(m.getUUID("Id"),m.getUUID("Author"),m.getString("Name"),m.getString("Text"),m.getLong("Time")));}for(Tag value:t.getList("Marks",10)){var m=(CompoundTag)value;if(room.marks.size()<64&&m.getString("Text").length()<=96&&Math.abs((long)m.getInt("X1"))<=29999984&&Math.abs((long)m.getInt("Z1"))<=29999984&&Math.abs((long)m.getInt("X2"))<=29999984&&Math.abs((long)m.getInt("Z2"))<=29999984){var mark=new Mark(m.getUUID("Id"),m.getUUID("Author"),m.getString("Text"),m.getInt("X1"),m.getInt("Z1"),m.getInt("X2"),m.getInt("Z2"),m.getBoolean("Approved"));room.marks.put(mark.id,mark);}}for(Tag value:t.getList("Receipts",11))if(room.receipts.size()<256)room.receipts.add(NbtUtils.loadUUID(value));}for(Tag raw:root.getList("Recruiting",10)){var t=(CompoundTag)raw;if(d.recruiting.size()<4096&&(t.getInt("Interests")&63)!=0)d.recruiting.put(t.getUUID("Id"),t.getInt("Interests")&63);}return d;}
}
